package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// Code written for Go 1.21 and older, in a module that says go 1.21.
var files = map[string]string{
	"go.mod": "module example.com/old\n\ngo 1.21\n",
	"old.go": `package old

import "fmt"

func Show(v interface{}) { fmt.Println(v) }

func Smaller(a, b int) int {
	m := a
	if b < m {
		m = b
	}
	return m
}

func Squares(n int) (out []int) {
	for i := 0; i < n; i++ {
		out = append(out, i*i)
	}
	return out
}

func PrintAll(names []string) {
	for _, n := range names {
		n := n
		defer func() { fmt.Println(n) }()
	}
}
`,
}

func main() {
	dir, err := os.MkdirTemp("", "old-")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	for name, body := range files {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o644); err != nil {
			panic(err)
		}
	}

	gocmd(dir, "fix", "-diff", ".") // preview only
	gocmd(dir, "fix", ".")          // apply
	gocmd(dir, "get", "go@1.22.0")  // raise the module's Go version
	gocmd(dir, "fix", "-diff", ".")
}

// gocmd runs the go command offline in dir. The diff's ---/+++ header lines
// hold absolute temp paths, so they are dropped.
func gocmd(dir string, args ...string) {
	cmd := exec.Command("go", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "GOTOOLCHAIN=local", "GOPROXY=off")
	out, err := cmd.CombinedOutput()
	fmt.Printf("$ go %s\n", strings.Join(args, " "))
	for line := range strings.Lines(string(out)) {
		if !strings.HasPrefix(line, "--- ") && !strings.HasPrefix(line, "+++ ") {
			fmt.Print(line)
		}
	}
	if err != nil {
		fmt.Printf("(%v)\n", err)
	}
}

files.examples/02_go_line.go:
package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

const mainGo = `package main

import "fmt"

func main() {
	for i := range 3 { // range over an int: Go 1.22
		fmt.Print(i)
	}
	fmt.Println()
}
`

func main() {
	dir, err := os.MkdirTemp("", "golines-")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	write(dir, "main.go", mainGo)

	// The go line is the language version: newer syntax is a compile error.
	write(dir, "go.mod", "module example.com/tc\n\ngo 1.21\n")
	gocmd(dir, "local", "run", ".")

	write(dir, "go.mod", "module example.com/tc\n\ngo 1.22\n")
	gocmd(dir, "local", "run", ".")

	// It is also the minimum toolchain. local refuses; auto (the default)
	// tries to download the toolchain go.mod asks for.
	write(dir, "go.mod", "module example.com/tc\n\ngo 1.99\n")
	gocmd(dir, "local", "run", ".")
	gocmd(dir, "auto", "run", ".")
}

func write(dir, name, body string) {
	if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o644); err != nil {
		panic(err)
	}
}

// gocmd runs the go command in dir with the given GOTOOLCHAIN. GOPROXY=off
// makes any download fail at once instead of reaching the network.
func gocmd(dir, toolchain string, args ...string) {
	cmd := exec.Command("go", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "GOTOOLCHAIN="+toolchain, "GOPROXY=off")
	out, err := cmd.CombinedOutput()
	fmt.Printf("$ GOTOOLCHAIN=%s go %s\n%s", toolchain, strings.Join(args, " "), filepath.ToSlash(string(out)))
	if err != nil {
		fmt.Printf("(%v)\n", err)
	}
}

files.examples/03_fix_inline.go:
package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// A library renamed Format to Lira and kept the old name as a one-line
// wrapper marked //go:fix inline. The app still calls Format.
var files = map[string]string{
	"go.mod": "module example.com/shop\n\ngo 1.27\n",
	"money/money.go": `package money

import "fmt"

// Format formats an amount given in kuruş.
//
// Deprecated: use [Lira].
//
//go:fix inline
func Format(kurus int) string { return Lira(kurus) }

// Lira formats an amount given in kuruş as Turkish lira.
func Lira(kurus int) string { return fmt.Sprintf("%d,%02d TL", kurus/100, kurus%100) }
`,
	"main.go": `package main

import (
	"fmt"

	"example.com/shop/money"
)

func main() { fmt.Println(money.Format(1250)) }
`,
}

func main() {
	dir, err := os.MkdirTemp("", "shop-")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	for name, body := range files {
		p := filepath.Join(dir, name)
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			panic(err)
		}
		if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
			panic(err)
		}
	}

	gocmd(dir, "fix", "-inline", "-diff", "./...") // only the inline fixer
	gocmd(dir, "fix", "-inline", "./...")
	gocmd(dir, "run", ".")
}

// gocmd runs the go command offline in dir. The diff's ---/+++ header lines
// hold absolute temp paths, so they are dropped.
func gocmd(dir string, args ...string) {
	cmd := exec.Command("go", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "GOTOOLCHAIN=local", "GOPROXY=off")
	out, err := cmd.CombinedOutput()
	fmt.Printf("$ go %s\n", strings.Join(args, " "))
	for line := range strings.Lines(string(out)) {
		if !strings.HasPrefix(line, "--- ") && !strings.HasPrefix(line, "+++ ") {
			fmt.Print(line)
		}
	}
	if err != nil {
		fmt.Printf("(%v)\n", err)
	}
}

